import { createServer, Tool, z } from '@nitrostack/core';
import { WustlClassifier } from './detection/classifier.js';
import { getMitreMapping } from './agent/mitre.js';
import { engineManager } from './engine_runner.js';
import { clearAllDataStores } from '../data/database_setup.js';
import {
  AssetInfoController,
  TicketingController,
  ContainmentController,
  SessionController,
  querySqlite,
  INCIDENTS_DB,
  TICKETS_DB,
  SESSIONS_DB
} from './mcp_servers/mcp_servers.js';

const classifier = new WustlClassifier();
const assetInfo = new AssetInfoController();
const ticketing = new TicketingController();
const containment = new ContainmentController();
const sessionCtrl = new SessionController();

const server = createServer({
  name: 'intrusion',
  version: '1.0.0',
  description: 'NitroStack OT Security Response Server & Autonomous Engine Controller.',
});

// 0. Tool: clear_all_data_stores (RESET DATA STORES & CSV FILES)
server.tool(
  new Tool({
    name: 'clear_all_data_stores',
    description: 'Clear all historical data stores (incidents.sqlite, tickets.sqlite, sessions.sqlite, and single CSV files incidents.csv, tickets.csv, proposals.csv, sessions.csv). Starts fresh.',
    inputSchema: z.object({}).passthrough(),
    handler: async () => {
      await clearAllDataStores();
      return { status: "SUCCESS", message: "All SQLite databases and single CSV stores cleared and reset successfully." };
    }
  })
);

// 1. Tool: start_engine / run_engine (PROCESSES TELEMETRY EVENTS LIVE, UPDATING DB & CSV FOR EVERY PACKET, PROMPTING APPROVAL IMMEDIATELY)
server.tool(
  new Tool({
    name: 'start_engine',
    description: 'Run real-time intrusion detection engine session. Updates SQLite DB and single CSV files for EVERY network traffic packet. Immediately outputs High/Critical severity alerts and approval prompts directly in Chat.',
    inputSchema: z.object({
      event_count: z.number().optional().default(15).describe('Number of telemetry packets to stream in this step (default 15)')
    }).passthrough(),
    handler: async (rawInput) => {
      const input = (rawInput as any) || {};
      const count = Number(input.event_count || 15);
      return engineManager.runLiveSessionStep(count);
    }
  })
);

// Alias: run_engine calls start_engine handler logic
server.tool(
  new Tool({
    name: 'run_engine',
    description: 'Run real-time intrusion detection engine session. Updates SQLite DB and single CSV files for EVERY network traffic packet. Immediately outputs High/Critical severity alerts and approval prompts directly in Chat.',
    inputSchema: z.object({
      event_count: z.number().optional().default(15).describe('Number of telemetry packets to stream in this step (default 15)')
    }).passthrough(),
    handler: async (rawInput) => {
      const input = (rawInput as any) || {};
      const count = Number(input.event_count || 15);
      return engineManager.runLiveSessionStep(count);
    }
  })
);

// 2. Tool: stop_engine (STOPS ENGINE & RETURNS SESSION REPORT)
server.tool(
  new Tool({
    name: 'stop_engine',
    description: 'Stop the active continuous engine session, finalize session records in sessions.sqlite, and return complete session summary, tickets, proposals, and pending action items.',
    inputSchema: z.object({}).passthrough(),
    handler: async () => {
      return engineManager.stopEngine();
    }
  })
);

// 3. Tool: get_engine_status (CHECKS REAL-TIME ENGINE STATE & PAUSE STATUS)
server.tool(
  new Tool({
    name: 'get_engine_status',
    description: 'Check if the continuous engine is running or paused for CRITICAL attack approval, active session_id, and live counts of events processed so far.',
    inputSchema: z.object({}).passthrough(),
    handler: async () => {
      return engineManager.getStatus();
    }
  })
);

// 4. Tool: get_session_details (RETRIEVES ATTACKS, TICKETS, PROPOSALS SEPARATELY PER SESSION)
server.tool(
  new Tool({
    name: 'get_session_details',
    description: 'Retrieve stored attack telemetry, work order tickets, and proposals filtered strictly by session_id.',
    inputSchema: z.object({
      session_id: z.string().describe('Target session ID (e.g. SES-XXXXXX)')
    }).passthrough(),
    handler: async (rawInput) => {
      const input = (rawInput as any) || {};
      const sid = input.session_id;
      if (!sid) return { error: "session_id parameter is required" };

      const attacks = querySqlite(INCIDENTS_DB, "SELECT * FROM incidents WHERE session_id = ?", [sid]);
      const tickets = querySqlite(TICKETS_DB, "SELECT * FROM tickets WHERE session_id = ?", [sid]);
      const proposals = querySqlite(TICKETS_DB, "SELECT * FROM proposals WHERE session_id = ?", [sid]);

      return {
        session_id: sid,
        total_attacks: attacks.length,
        total_tickets: tickets.length,
        total_proposals: proposals.length,
        attacks,
        tickets,
        proposals
      };
    }
  })
);

// 5. Tool: get_summary_report (EXECUTIVE REPORT GENERATION)
server.tool(
  new Tool({
    name: 'get_summary_report',
    description: 'Retrieve executive summary report of ALREADY STORED events and sessions in SQLite database.',
    inputSchema: z.object({}).passthrough(),
    handler: async (rawInput, context) => {
      context.logger.info('Running get_summary_report');
      try {
        const events = querySqlite(INCIDENTS_DB, "SELECT * FROM incidents");
        const tickets = querySqlite(TICKETS_DB, "SELECT * FROM tickets");
        const proposals = querySqlite(TICKETS_DB, "SELECT * FROM proposals");
        const sessions = sessionCtrl.getStoredSessions();

        let normalCount = 0, lowCount = 0, mediumCount = 0, highCount = 0, criticalCount = 0;
        for (const ev of events) {
          const sev = (ev.severity || "").toUpperCase();
          if (sev === "NORMAL" || ev.traffic_type === "normal") normalCount++;
          else if (sev === "LOW") lowCount++;
          else if (sev === "MEDIUM") mediumCount++;
          else if (sev === "HIGH") highCount++;
          else if (sev === "CRITICAL") criticalCount++;
        }

        const pendingProposals = proposals.filter((p: any) => p.status === "pending_approval");

        return {
          report_title: "OT SECURITY EXECUTIVE SUMMARY REPORT",
          generated_at: new Date().toISOString(),
          total_sessions_run: sessions.length,
          total_historical_events_stored: events.length,
          breakdown: {
            normal_operational_traffic: normalCount,
            low_severity_attacks: lowCount,
            medium_severity_attacks: mediumCount,
            high_severity_attacks: highCount,
            critical_severity_attacks: criticalCount
          },
          total_tickets_created: tickets.length,
          total_proposals_generated: proposals.length,
          pending_proposals_requiring_approval: pendingProposals,
          recent_sessions: sessions.slice(0, 5)
        };
      } catch (err: any) {
        return { error: err.message, status: 'failed' };
      }
    }
  })
);

// 6. Tool: list_stored_sessions (SESSION QUERYING)
server.tool(
  new Tool({
    name: 'list_stored_sessions',
    description: 'Retrieve details of execution sessions stored in sessions.sqlite.',
    inputSchema: z.object({}).passthrough(),
    handler: async (rawInput, context) => {
      context.logger.info('Running list_stored_sessions');
      try {
        return sessionCtrl.getStoredSessions();
      } catch (err: any) {
        return [];
      }
    }
  })
);

// 7. Tool: list_stored_events (HISTORICAL TELEMETRY)
server.tool(
  new Tool({
    name: 'list_stored_events',
    description: 'Query historical security telemetry events stored in incidents.sqlite.',
    inputSchema: z.object({
      limit: z.number().optional().default(20).describe('Max events to retrieve (default 20)'),
      severity: z.string().optional().describe('Filter by severity: LOW, MEDIUM, HIGH, CRITICAL, NORMAL')
    }).passthrough(),
    handler: async (rawInput, context) => {
      context.logger.info('Running list_stored_events');
      try {
        const input = (rawInput as any) || {};
        return assetInfo.getStoredEvents(Number(input.limit || 20), input.severity);
      } catch (err: any) {
        return [];
      }
    }
  })
);

// 8. Tool: get_stored_tickets (TICKET MANAGEMENT)
server.tool(
  new Tool({
    name: 'get_stored_tickets',
    description: 'Retrieve work order tickets stored in tickets.sqlite created during engine sessions.',
    inputSchema: z.object({}).passthrough(),
    handler: async (rawInput, context) => {
      context.logger.info('Running get_stored_tickets');
      try {
        return ticketing.getStoredTickets();
      } catch (err: any) {
        return [];
      }
    }
  })
);

// 9. Tool: get_stored_proposals (PROPOSAL MANAGEMENT)
server.tool(
  new Tool({
    name: 'get_stored_proposals',
    description: 'Retrieve containment & isolation proposals stored in tickets.sqlite awaiting operator approval.',
    inputSchema: z.object({}).passthrough(),
    handler: async (rawInput, context) => {
      context.logger.info('Running get_stored_proposals');
      try {
        return containment.getStoredProposals();
      } catch (err: any) {
        return [];
      }
    }
  })
);

// 10. Tool: get_asset (ASSET INVENTORY)
server.tool(
  new Tool({
    name: 'get_asset',
    description: 'Lookup asset metadata, zone, subnet, and criticality from assets.csv.',
    inputSchema: z.object({
      ip_or_id: z.string().optional().describe('Target IP address or asset_id')
    }).passthrough(),
    handler: async (rawInput, context) => {
      context.logger.info('Running get_asset');
      try {
        const input = (rawInput as any) || {};
        const ipOrId = input.ip_or_id || input.ip || input.asset_id || (typeof rawInput === 'string' ? rawInput : '10.0.4.5');
        return assetInfo.getAsset(String(ipOrId).trim());
      } catch (err: any) {
        return { error: err.message, criticality: 'critical', type: 'Unknown' };
      }
    }
  })
);

// 11. Tool: get_mitre_mapping (MITRE ATT&CK LOOKUP)
server.tool(
  new Tool({
    name: 'get_mitre_mapping',
    description: 'Map an attack classification to MITRE ATT&CK for ICS matrix.',
    inputSchema: z.object({
      attack_type: z.string().optional().describe('Attack type string')
    }).passthrough(),
    handler: async (rawInput, context) => {
      context.logger.info('Running get_mitre_mapping');
      try {
        const input = (rawInput as any) || {};
        const attackType = input.attack_type || (typeof rawInput === 'string' ? rawInput : 'Reconn');
        return getMitreMapping(attackType);
      } catch (err: any) {
        return getMitreMapping('Reconn');
      }
    }
  })
);

// 12. Tool: execute_isolation (OPERATOR SIGN-OFF - STOPS ENGINE ON CRITICAL APPROVAL)
server.tool(
  new Tool({
    name: 'execute_isolation',
    description: 'Execute network isolation for a proposal stored in tickets.sqlite. REQUIRES mandatory approved_by operator sign-off. IF THE PROPOSAL IS CRITICAL, AUTOMATICALLY STOPS THE ENGINE SESSION FOR PLANT SAFETY.',
    inputSchema: z.object({
      proposal_id: z.string().optional().describe('Target proposal ID (e.g. PROP-XXXXXX)'),
      approved_by: z.string().optional().describe('Human operator ID/role giving sign-off')
    }).passthrough(),
    handler: async (rawInput, context) => {
      context.logger.info('Running execute_isolation');
      try {
        const input = (rawInput as any) || {};
        const proposalId = input.proposal_id || 'PROP-001';
        const approvedBy = input.approved_by || 'operator_plant_mgr';

        const execRes = containment.executeIsolation(proposalId, approvedBy);

        // Check if engine is paused for Critical Approval
        if (engineManager.isPaused() || engineManager.getCriticalProposalId() === proposalId) {
          const sessionStopRes = engineManager.notifyCriticalApprovalAndStop(proposalId, approvedBy);
          return {
            execution_result: execRes,
            critical_safety_notice: "CRITICAL SEVERITY ATTACK ISOLATION APPROVED BY OPERATOR. SESSION HAS BEEN TERMINATED FOR PLANT SAFETY.",
            session_result: sessionStopRes
          };
        }

        return execRes;
      } catch (err: any) {
        return { status: 'BLOCKED', error: err.message };
      }
    }
  })
);

server.start().catch((error) => {
  console.error('Failed to start server:', error);
  process.exit(1);
});

/**
 * NitroStack OT Security Engine Runner & Continuous Background Streaming Controller
 * Core Engine Pipeline shared by both NitroStack MCP Server and CLI Terminal
 */

import { WustlClassifier } from "./detection/classifier.js";
import {
  AssetInfoController,
  TicketingController,
  ContainmentController,
  NotificationController,
  SessionController,
  querySqlite,
  INCIDENTS_DB,
  TICKETS_DB
} from "./mcp_servers/mcp_servers.js";
import { getMitreMapping } from "./agent/mitre.js";

const SYSTEM_DAMAGE_EXPLANATIONS = {
  high: [
    "High System Blast Radius: Threat targeting SCADA Historian / Engineering Node. Risk of unauthorized ladder logic modification, setpoint drift, or Fieldbus I/O write command injection.",
    "High System Blast Radius: Threat targeting Industrial Gateway (GW-01). Potential spoofing of inter-zone control commands resulting in secondary loop perturbation.",
    "High System Blast Radius: Unauthorized write attempt on Operator HMI. Risk of false process parameter displays leading to operator misjudgment."
  ],
  critical: [
    "CATASTROPHIC SYSTEM IMPACT: Direct threat targeting Primary Process Controller (PLC-03/04)! Extreme risk of loss of control loop (LCL), pressure/thermal runaway, Safety Instrumented System (SIS) trip lockouts, or severe physical equipment destruction.",
    "CATASTROPHIC SYSTEM IMPACT: Cyber attack targeting Safety Instrumented System (SIS-01)! Potential emergency plant trip (EPT), turbine over-speeding, or pressure vessel rupture.",
    "CATASTROPHIC SYSTEM IMPACT: Multi-asset campaign threat targeting primary controllers. Severe risk of total operational blackout or physical infrastructure damage."
  ]
};

const ASSET_POOL = [
  { ip: "10.0.4.1", id: "PLC-01", name: "Primary Pump PLC", zone: "Zone 2", subnet: "10.0.4.0/24", criticality: "medium" },
  { ip: "10.0.4.2", id: "PLC-02", name: "Turbine Speed PLC", zone: "Zone 2", subnet: "10.0.4.0/24", criticality: "high" },
  { ip: "10.0.4.3", id: "PLC-03", name: "Reactor Pressure PLC", zone: "Zone 2", subnet: "10.0.4.0/24", criticality: "critical" },
  { ip: "10.0.4.5", id: "PLC-04", name: "Emergency Shutdown PLC", zone: "Zone 2", subnet: "10.0.4.0/24", criticality: "critical" },
  { ip: "10.0.4.10", id: "HMI-01", name: "Operator Touch Screen", zone: "Zone 2", subnet: "10.0.4.0/24", criticality: "low" },
  { ip: "10.0.4.11", id: "HMI-02", name: "Control Room Console", zone: "Zone 2", subnet: "10.0.4.0/24", criticality: "medium" },
  { ip: "10.0.4.20", id: "HIST-01", name: "SCADA Process Historian", zone: "Zone 2", subnet: "10.0.4.0/24", criticality: "high" },
  { ip: "10.0.4.50", id: "EWS-01", name: "Engineering Workstation", zone: "Zone 1", subnet: "10.0.4.0/24", criticality: "critical" },
  { ip: "10.0.5.5", id: "SENSOR-01", name: "Temperature Transducer", zone: "Zone 3", subnet: "10.0.5.0/24", criticality: "low" },
  { ip: "10.0.5.6", id: "SENSOR-02", name: "Flow Rate Sensor", zone: "Zone 3", subnet: "10.0.5.0/24", criticality: "low" },
  { ip: "10.0.5.12", id: "ACTUATOR-01", name: "Control Valve Actuator", zone: "Zone 3", subnet: "10.0.5.0/24", criticality: "medium" },
  { ip: "10.0.5.1", id: "GATEWAY-01", name: "OT/IT Firewall Gateway", zone: "Zone 3", subnet: "10.0.5.0/24", criticality: "high" }
];

const ATTACK_TYPES = ["scanning", "Reconn", "DoS", "CommInj", "Backdoor"];
const PROTOCOLS = ["Modbus/TCP", "EtherNet/IP", "PROFINET", "TCP/IP", "HTTP"];

function getRandomItem<T>(arr: T[]): T {
  return arr[Math.floor(Math.random() * arr.length)];
}

function getRandomNumber(min: number, max: number): number {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

export function generateSingleEvent(sessionId: string, seqNumber: number) {
  const asset = getRandomItem(ASSET_POOL);
  const isNormal = Math.random() < 0.6;
  const attackType = isNormal ? "normal" : getRandomItem(ATTACK_TYPES);
  const protocol = getRandomItem(PROTOCOLS);
  const srcIp = isNormal
    ? `10.0.4.${getRandomNumber(100, 200)}`
    : `10.0.${getRandomNumber(1, 10)}.${getRandomNumber(10, 250)}`;

  return {
    event_id: `EVT-${sessionId.replace("SES-", "")}-${String(seqNumber).padStart(3, "0")}`,
    session_id: sessionId,
    src_ip: srcIp,
    dst_ip: asset.ip,
    asset_id: asset.id,
    asset_name: asset.name,
    zone: asset.zone,
    subnet: asset.subnet,
    configured_criticality: asset.criticality,
    is_normal: isNormal,
    attack_type: attackType,
    protocol: protocol,
    total_packets: getRandomNumber(120, 4800),
    flow_features: isNormal
      ? { Mean: 0.01, Dport: 502, SrcPkts: 10, DstPkts: 10, TotPkts: 200 }
      : {
          Mean: Number((Math.random() * 0.25).toFixed(4)),
          Dport: getRandomItem([502, 44818, 102, 80, 443]),
          SrcPkts: getRandomNumber(15, 150),
          DstPkts: getRandomNumber(15, 140),
          TotPkts: getRandomNumber(300, 4800)
        }
  };
}

class ContinuousEngineManager {
  private activeSessionId: string | null = null;
  private intervalTimer: NodeJS.Timeout | null = null;
  private isPausedForCritical = false;
  private criticalProposalId: string | null = null;
  private criticalAssetId: string | null = null;
  private seqNumber = 0;
  private normalCount = 0;
  private lowCount = 0;
  private mediumCount = 0;
  private highCount = 0;
  private criticalCount = 0;
  private ticketsCount = 0;
  private proposalsCount = 0;

  private classifier = new WustlClassifier();
  private assetInfo = new AssetInfoController();
  private ticketing = new TicketingController();
  private containment = new ContainmentController();
  private notifier = new NotificationController();
  private sessionCtrl = new SessionController();

  public isRunning(): boolean {
    return this.activeSessionId !== null && !this.isPausedForCritical;
  }

  public isPaused(): boolean {
    return this.isPausedForCritical;
  }

  public getActiveSessionId(): string | null {
    return this.activeSessionId;
  }

  public getCriticalProposalId(): string | null {
    return this.criticalProposalId;
  }

  public getStatus() {
    const pendingProposals = this.activeSessionId
      ? querySqlite(TICKETS_DB, "SELECT * FROM proposals WHERE session_id = ? AND status = 'pending_approval'", [this.activeSessionId])
      : [];

    const activeApprovalRequests = pendingProposals.map((p: any) => ({
      proposal_id: p.proposal_id,
      asset_id: p.asset_id,
      zone: p.zone,
      reason: p.reason,
      mitre_id: p.mitre_id,
      is_critical: p.reason.includes("CRITICAL"),
      approval_prompt: `approve proposal ${p.proposal_id} as plant_manager`,
      stream_behavior: p.reason.includes("CRITICAL")
        ? "SESSION PAUSED FOR PLANT SAFETY. Approval will isolate asset and terminate session."
        : "SIMULTANEOUS APPROVAL REQUESTED. Background network streaming continues uninterrupted."
    }));

    return {
      is_running: this.isRunning(),
      is_paused_awaiting_critical_approval: this.isPausedForCritical,
      critical_proposal_id: this.criticalProposalId,
      critical_asset_id: this.criticalAssetId,
      active_session_id: this.activeSessionId,
      events_processed_so_far: this.seqNumber,
      normal_operational_traffic: this.normalCount,
      low_severity_attacks: this.lowCount,
      medium_severity_attacks: this.mediumCount,
      high_severity_attacks: this.highCount,
      critical_severity_attacks: this.criticalCount,
      work_orders_created: this.ticketsCount,
      proposals_generated: this.proposalsCount,
      active_approval_requests: activeApprovalRequests,
      operator_action_required: activeApprovalRequests.length > 0
        ? `Action Required: ${activeApprovalRequests.length} proposal(s) awaiting approval. Ask me: "${activeApprovalRequests[0].approval_prompt}"`
        : "No pending operator actions required."
    };
  }

  public startEngine(): { status: string; session_id: string; message: string } {
    if (this.activeSessionId && !this.isPausedForCritical) {
      return {
        status: "ALREADY_RUNNING",
        session_id: this.activeSessionId,
        message: `Engine is already running session [${this.activeSessionId}] in continuous streaming mode.`
      };
    }

    this.activeSessionId = `SES-${Date.now().toString(36).toUpperCase()}-${Math.floor(100 + Math.random() * 900)}`;
    this.isPausedForCritical = false;
    this.criticalProposalId = null;
    this.criticalAssetId = null;
    this.seqNumber = 0;
    this.normalCount = 0;
    this.lowCount = 0;
    this.mediumCount = 0;
    this.highCount = 0;
    this.criticalCount = 0;
    this.ticketsCount = 0;
    this.proposalsCount = 0;

    this.sessionCtrl.startSession(this.activeSessionId);

    // Ingest 1 event every 1.5 seconds in background stream
    this.intervalTimer = setInterval(() => {
      this.processNextEvent();
    }, 1500);

    return {
      status: "STARTED",
      session_id: this.activeSessionId,
      message: `Continuous engine session [${this.activeSessionId}] started successfully. Streaming network telemetry in background.`
    };
  }

  public runLiveSessionStep(eventCount: number = 10): {
    status: string;
    session_id: string;
    events_processed: number;
    is_paused_for_critical: boolean;
    critical_severity_detected?: any;
    pending_approval_requests: any[];
    session_summary: any;
    operator_action_prompt: string;
  } {
    if (!this.activeSessionId) {
      this.activeSessionId = `SES-${Date.now().toString(36).toUpperCase()}-${Math.floor(100 + Math.random() * 900)}`;
      this.isPausedForCritical = false;
      this.criticalProposalId = null;
      this.criticalAssetId = null;
      this.seqNumber = 0;
      this.normalCount = 0;
      this.lowCount = 0;
      this.mediumCount = 0;
      this.highCount = 0;
      this.criticalCount = 0;
      this.ticketsCount = 0;
      this.proposalsCount = 0;

      this.sessionCtrl.startSession(this.activeSessionId);
    }

    const initialSeq = this.seqNumber;
    let criticalHit: any = null;

    for (let i = 0; i < eventCount; i++) {
      if (this.isPausedForCritical) break;
      this.processNextEvent();

      if (this.isPausedForCritical) {
        const lastIncident = querySqlite(INCIDENTS_DB, "SELECT * FROM incidents WHERE session_id = ? ORDER BY rowid DESC LIMIT 1", [this.activeSessionId])[0];
        const lastProposal = querySqlite(TICKETS_DB, "SELECT * FROM proposals WHERE session_id = ? ORDER BY rowid DESC LIMIT 1", [this.activeSessionId])[0];
        criticalHit = { incident: lastIncident, proposal: lastProposal };
        break;
      }
    }

    const pendingProposals = querySqlite(TICKETS_DB, "SELECT * FROM proposals WHERE session_id = ? AND status = 'pending_approval'", [this.activeSessionId]);

    const formattedRequests = pendingProposals.map((p: any) => ({
      proposal_id: p.proposal_id,
      asset_id: p.asset_id,
      zone: p.zone,
      reason: p.reason,
      mitre_id: p.mitre_id,
      is_critical: p.reason.includes("CRITICAL"),
      approval_prompt: `approve proposal ${p.proposal_id} as plant_manager`,
      action_instruction: `Ask me: "approve proposal ${p.proposal_id} as plant_manager"`
    }));

    let actionPrompt = "No pending approval required.";
    if (criticalHit) {
      actionPrompt = `🚨 CRITICAL ATTACK DETECTED! Session PAUSED on asset ${criticalHit.proposal.asset_id}. Ask me: "approve proposal ${criticalHit.proposal.proposal_id} as plant_manager" to isolate asset and terminate session.`;
    } else if (formattedRequests.length > 0) {
      actionPrompt = `⚠️ HIGH SEVERITY ATTACK DETECTED! ${formattedRequests.length} proposal(s) pending approval. Ask me: "${formattedRequests[0].approval_prompt}" to execute revocation (streaming continues).`;
    }

    return {
      status: this.isPausedForCritical ? "PAUSED_AWAITING_CRITICAL_APPROVAL" : "RUNNING",
      session_id: this.activeSessionId,
      events_processed: this.seqNumber - initialSeq,
      is_paused_for_critical: this.isPausedForCritical,
      critical_severity_detected: criticalHit,
      pending_approval_requests: formattedRequests,
      session_summary: {
        total_events_processed_so_far: this.seqNumber,
        normal_operational_traffic: this.normalCount,
        low_severity_attacks: this.lowCount,
        medium_severity_attacks: this.mediumCount,
        high_severity_attacks: this.highCount,
        critical_severity_attacks: this.criticalCount,
        work_orders_created: this.ticketsCount,
        proposals_generated: this.proposalsCount
      },
      operator_action_prompt: actionPrompt
    };
  }

  private processNextEvent() {
    if (!this.activeSessionId || this.isPausedForCritical) return;
    this.seqNumber++;
    const event = generateSingleEvent(this.activeSessionId, this.seqNumber);
    const asset = this.assetInfo.getAsset(event.dst_ip);

    const clfResult = this.classifier.predictFlow(event.flow_features);
    const detectedLabel = event.is_normal ? "normal" : (clfResult.attack_label !== "normal" ? clfResult.attack_label : event.attack_type);

    if (detectedLabel === "normal") {
      this.normalCount++;
      this.assetInfo.recordIncident({
        event_id: event.event_id,
        timestamp: new Date().toISOString(),
        session_id: this.activeSessionId,
        asset_id: asset.asset_id,
        src_ip: event.src_ip,
        dst_ip: event.dst_ip,
        attack_type: "normal",
        severity: "NORMAL",
        mitre_id: "N/A",
        zone: asset.zone,
        subnet: asset.subnet,
        traffic_type: "normal",
        system_damage: "Zero"
      });
      return;
    }

    const mitre = getMitreMapping(detectedLabel);
    const severity = asset.criticality.toLowerCase();

    if (severity === "low") {
      this.lowCount++;
      this.ticketing.createWorkOrder(asset.asset_id, "P4", mitre.mitre_id, `Low risk ${detectedLabel} logged`, "Heightened monitoring", undefined, this.activeSessionId);
      this.ticketsCount++;

      this.assetInfo.recordIncident({
        event_id: event.event_id,
        timestamp: new Date().toISOString(),
        session_id: this.activeSessionId,
        asset_id: asset.asset_id,
        src_ip: event.src_ip,
        dst_ip: event.dst_ip,
        attack_type: detectedLabel,
        severity: "LOW",
        mitre_id: mitre.mitre_id,
        zone: asset.zone,
        subnet: asset.subnet,
        traffic_type: "attack",
        system_damage: "Minimal"
      });

    } else if (severity === "medium") {
      this.mediumCount++;
      this.ticketing.createWorkOrder(asset.asset_id, "P3", mitre.mitre_id, `Medium risk ${detectedLabel} rate-limited`, "Rate-limited MCP tool call", undefined, this.activeSessionId);
      this.ticketsCount++;

      this.assetInfo.recordIncident({
        event_id: event.event_id,
        timestamp: new Date().toISOString(),
        session_id: this.activeSessionId,
        asset_id: asset.asset_id,
        src_ip: event.src_ip,
        dst_ip: event.dst_ip,
        attack_type: detectedLabel,
        severity: "MEDIUM",
        mitre_id: mitre.mitre_id,
        zone: asset.zone,
        subnet: asset.subnet,
        traffic_type: "attack",
        system_damage: "Moderate transient write restriction"
      });

    } else if (severity === "high") {
      // HIGH SEVERITY: SIMULTANEOUSLY ASKS APPROVAL FOR REVOCATION, BUT NETWORK PACKET STREAM CONTINUES UNINTERRUPTED!
      this.highCount++;
      const damageExplanation = getRandomItem(SYSTEM_DAMAGE_EXPLANATIONS.high);
      const propRes = this.containment.proposeIsolation(asset.asset_id, `High threat (${mitre.mitre_id}): ${detectedLabel}`, mitre.mitre_id, asset.zone, this.activeSessionId);
      this.proposalsCount++;

      this.ticketing.createWorkOrder(asset.asset_id, "P2", mitre.mitre_id, `High risk ${detectedLabel} session revocation proposed`, `Proposed session revocation [${propRes.proposal_id}]`, undefined, this.activeSessionId);
      this.ticketsCount++;

      this.assetInfo.recordIncident({
        event_id: event.event_id,
        timestamp: new Date().toISOString(),
        session_id: this.activeSessionId,
        asset_id: asset.asset_id,
        src_ip: event.src_ip,
        dst_ip: event.dst_ip,
        attack_type: detectedLabel,
        severity: "HIGH",
        mitre_id: mitre.mitre_id,
        zone: asset.zone,
        subnet: asset.subnet,
        traffic_type: "attack",
        system_damage: damageExplanation
      });

      this.notifier.notify("Plant Manager", "P2", "HIGH_ALERT_APPROVAL_REQUEST", {
        event_id: event.event_id,
        asset_id: asset.asset_id,
        criticality: asset.criticality,
        zone: asset.zone,
        mitre_id: mitre.mitre_id,
        attack_type: detectedLabel,
        src_ip: event.src_ip,
        dst_ip: event.dst_ip,
        total_packets: event.total_packets,
        action_taken_or_proposed: `HIGH SEVERITY ALERT: Proposed session revocation [${propRes.proposal_id}]. Please approve! Network streaming continues uninterrupted.`
      });

    } else {
      // CRITICAL SEVERITY ONLY: SIMULTANEOUSLY ASKS APPROVAL, PAUSES SESSION STREAMING, AND TERMINATES SESSION UPON APPROVAL!
      this.criticalCount++;
      const damageExplanation = getRandomItem(SYSTEM_DAMAGE_EXPLANATIONS.critical);
      const propRes = this.containment.proposeIsolation(asset.asset_id, `CRITICAL THREAT EMERGENCY PAUSE (${mitre.mitre_id}): ${detectedLabel}`, mitre.mitre_id, asset.zone, this.activeSessionId);
      this.proposalsCount++;

      const ticket = this.ticketing.createWorkOrder(asset.asset_id, "P1", mitre.mitre_id, `CRITICAL threat on ${asset.asset_id} - Session Paused awaiting operator approval`, `Propose failover + isolation [${propRes.proposal_id}]`, undefined, this.activeSessionId);
      this.ticketsCount++;

      this.assetInfo.recordIncident({
        event_id: event.event_id,
        timestamp: new Date().toISOString(),
        session_id: this.activeSessionId,
        asset_id: asset.asset_id,
        src_ip: event.src_ip,
        dst_ip: event.dst_ip,
        attack_type: detectedLabel,
        severity: "CRITICAL",
        mitre_id: mitre.mitre_id,
        zone: asset.zone,
        subnet: asset.subnet,
        traffic_type: "attack",
        system_damage: damageExplanation
      });

      this.notifier.notify("Safety Officer", "P1", "CRITICAL_EMERGENCY_HOLD", {
        event_id: event.event_id,
        asset_id: asset.asset_id,
        criticality: asset.criticality,
        zone: asset.zone,
        mitre_id: mitre.mitre_id,
        attack_type: detectedLabel,
        src_ip: event.src_ip,
        dst_ip: event.dst_ip,
        total_packets: event.total_packets,
        action_taken_or_proposed: `CRITICAL ATTACK DETECTED! Session PAUSED. Approval required for [${propRes.proposal_id}] to isolate asset and TERMINATE session.`
      });

      // PAUSE CONTINUOUS INGESTION ONLY FOR CRITICAL
      this.isPausedForCritical = true;
      this.criticalProposalId = propRes.proposal_id!;
      this.criticalAssetId = asset.asset_id;

      if (this.intervalTimer) {
        clearInterval(this.intervalTimer);
        this.intervalTimer = null;
      }
    }
  }

  public notifyCriticalApprovalAndStop(proposalId: string, approvedBy: string) {
    if (!this.activeSessionId) return null;

    const stopResult = this.stopEngine("critical_emergency_stop");
    return {
      ...stopResult,
      critical_mitigation: {
        proposal_id: proposalId,
        approved_by: approvedBy,
        target_asset: this.criticalAssetId,
        action: "Executed Critical Asset Isolation and Terminated Continuous Engine Session for System Safety."
      }
    };
  }

  public stopEngine(customStatus?: string): {
    status: string;
    session_id: string;
    message: string;
    session_summary: any;
    session_attacks: any[];
    session_tickets: any[];
    session_proposals: any[];
    pending_proposals_awaiting_approval: any[];
    operator_action_required: string;
  } {
    if (!this.activeSessionId) {
      return {
        status: "NOT_RUNNING",
        session_id: "N/A",
        message: "No active engine session is currently running.",
        session_summary: null,
        session_attacks: [],
        session_tickets: [],
        session_proposals: [],
        pending_proposals_awaiting_approval: [],
        operator_action_required: "None"
      };
    }

    if (this.intervalTimer) {
      clearInterval(this.intervalTimer);
      this.intervalTimer = null;
    }

    const sessionId = this.activeSessionId;
    this.activeSessionId = null;
    this.isPausedForCritical = false;
    this.criticalProposalId = null;
    this.criticalAssetId = null;

    const sessionAttacks = querySqlite(INCIDENTS_DB, "SELECT * FROM incidents WHERE session_id = ?", [sessionId]);
    const sessionTickets = querySqlite(TICKETS_DB, "SELECT * FROM tickets WHERE session_id = ?", [sessionId]);
    const sessionProposals = querySqlite(TICKETS_DB, "SELECT * FROM proposals WHERE session_id = ?", [sessionId]);

    const pendingProposals = sessionProposals.filter((p: any) => p.status === "pending_approval");
    const finalStatus = customStatus || (pendingProposals.length === 0 ? "completed" : "pending_operator_signoff");

    this.sessionCtrl.endSession(sessionId, {
      total_events: this.seqNumber,
      normal_count: this.normalCount,
      low_count: this.lowCount,
      medium_count: this.mediumCount,
      high_count: this.highCount,
      critical_count: this.criticalCount,
      tickets_count: this.ticketsCount,
      proposals_count: this.proposalsCount,
      status: finalStatus
    });

    const pendingFormatted = pendingProposals.map((p: any) => ({
      proposal_id: p.proposal_id,
      asset_id: p.asset_id,
      zone: p.zone,
      reason: p.reason,
      mitre_id: p.mitre_id,
      approval_instruction: `To approve this proposal, ask: "approve proposal ${p.proposal_id} as plant_manager"`
    }));

    return {
      status: "STOPPED",
      session_id: sessionId,
      message: `Engine session [${sessionId}] stopped successfully. Data stored separately for this session.`,
      session_summary: {
        total_events_processed: this.seqNumber,
        normal_operational_traffic: this.normalCount,
        low_severity_attacks: this.lowCount,
        medium_severity_attacks: this.mediumCount,
        high_severity_attacks: this.highCount,
        critical_severity_attacks: this.criticalCount,
        work_orders_created: this.ticketsCount,
        proposals_generated: this.proposalsCount,
        session_status: finalStatus
      },
      session_attacks: sessionAttacks,
      session_tickets: sessionTickets,
      session_proposals: sessionProposals,
      pending_proposals_awaiting_approval: pendingFormatted,
      operator_action_required: pendingProposals.length > 0
        ? `Action Required: ${pendingProposals.length} proposal(s) await your approval. Ask me: "approve proposal ${pendingProposals[0].proposal_id} as plant_manager"`
        : "No pending operator actions required."
    };
  }
}

export const engineManager = new ContinuousEngineManager();

export async function runEngineSession(eventCount: number = 20) {
  engineManager.startEngine();
  await new Promise(r => setTimeout(r, eventCount * 300));
  return engineManager.stopEngine();
}

