export function loadAsset(ipOrId: string): AssetRecord | null {
  if (!fs.existsSync(ASSETS_CSV)) return null;
  const content = fs.readFileSync(ASSETS_CSV, "utf-8");
  const lines = content.trim().split("\n").map(l => l.trim()).filter(Boolean);
  if (lines.length <= 1) return null;
  const headers = lines[0].split(",").map(h => h.trim());

  for (let i = 1; i < lines.length; i++) {
    const values = lines[i].split(",").map(v => v.trim());
    const row: Record<string, string> = {};
    headers.forEach((h, idx) => { row[h] = values[idx] || ""; });
    if (row["ip"] === ipOrId || row["asset_id"] === ipOrId) {
      return row as unknown as AssetRecord;
    }
  }
  return null;
}

import initSqlJs, { SqlJsStatic } from "sql.js";

let SQL: SqlJsStatic | null = null;
export const sqlPromise = initSqlJs().then(instance => {
  SQL = instance;
}).catch(err => {
  console.error("Failed to initialize sql.js in mcp_servers:", err);
});

function getSql(): SqlJsStatic | null {
  return SQL;
}

export function querySqlite(dbPath: string, sqlQuery: string, params: any[] = []): any[] {
  if (!fs.existsSync(dbPath)) return [];
  const sqlModule = getSql();
  if (!sqlModule) return [];
  try {
    const fileBuffer = fs.readFileSync(dbPath);
    const db = new sqlModule.Database(fileBuffer);
    const stmt = db.prepare(sqlQuery);
    stmt.bind(params);
    const rows: any[] = [];
    while (stmt.step()) {
      rows.push(stmt.getAsObject());
    }
    stmt.free();
    db.close();
    return rows;
  } catch {
    return [];
  }
}

export function executeSqlite(dbPath: string, sqlQuery: string, params: any[] = []): void {
  if (!fs.existsSync(dbPath)) return;
  const sqlModule = getSql();
  if (!sqlModule) return;
  try {
    const fileBuffer = fs.readFileSync(dbPath);
    const db = new sqlModule.Database(fileBuffer);
    db.run(sqlQuery, params);
    const data = db.export();
    fs.writeFileSync(dbPath, Buffer.from(data));
    db.close();
  } catch (err: any) {
    console.error("executeSqlite error:", err.message);
  }
}

function escapeCsv(val: any): string {
  const str = String(val ?? "").replace(/"/g, '""');
  return `"${str}"`;
}

export function syncIncidentsCsv(): void {
  const rows = querySqlite(INCIDENTS_DB, "SELECT * FROM incidents ORDER BY rowid ASC");
  const headers = ["event_id","timestamp","session_id","asset_id","src_ip","dst_ip","attack_type","severity","mitre_id","zone","subnet","traffic_type","system_damage"];
  const lines = [headers.map(h => `"${h}"`).join(",")];
  for (const r of rows) {
    lines.push(headers.map(h => escapeCsv(r[h])).join(","));
  }
  fs.writeFileSync(INCIDENTS_CSV, lines.join("\n"));
}

export function syncTicketsCsv(): void {
  const rows = querySqlite(TICKETS_DB, "SELECT * FROM tickets ORDER BY rowid ASC");
  const headers = ["ticket_id","session_id","asset_id","severity","mitre_id","description","action_field","campaign_id","status","created_at"];
  const lines = [headers.map(h => `"${h}"`).join(",")];
  for (const r of rows) {
    lines.push(headers.map(h => escapeCsv(r[h])).join(","));
  }
  fs.writeFileSync(TICKETS_CSV, lines.join("\n"));
}

export function syncProposalsCsv(): void {
  const rows = querySqlite(TICKETS_DB, "SELECT * FROM proposals ORDER BY rowid ASC");
  const headers = ["proposal_id","session_id","asset_id","zone","reason","mitre_id","status","approved_by","created_at"];
