}

export function syncSessionsCsv(): void {
  const rows = querySqlite(SESSIONS_DB, "SELECT * FROM sessions ORDER BY rowid ASC");
  const headers = ["session_id","start_time","end_time","total_events","normal_count","low_count","medium_count","high_count","critical_count","tickets_count","proposals_count","status"];
  const lines = [headers.map(h => `"${h}"`).join(",")];
