/**
 * Database Setup, Reset & Single CSV Persistence Schema
 * Manages SQLite databases & Single CSV Data Stores:
 *  - incidents.sqlite & incidents.csv
 *  - tickets.sqlite (tickets & proposals) & tickets.csv, proposals.csv
 *  - sessions.sqlite & sessions.csv
 */

import initSqlJs from "sql.js";
import * as fs from "fs";
import * as path from "path";
import { fileURLToPath } from "url";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

export const DATA_DIR = path.resolve(__dirname);
export const INCIDENTS_DB = path.join(DATA_DIR, "incidents.sqlite");
export const TICKETS_DB = path.join(DATA_DIR, "tickets.sqlite");
export const SESSIONS_DB = path.join(DATA_DIR, "sessions.sqlite");

export const INCIDENTS_CSV = path.join(DATA_DIR, "incidents.csv");
export const TICKETS_CSV = path.join(DATA_DIR, "tickets.csv");
export const PROPOSALS_CSV = path.join(DATA_DIR, "proposals.csv");
export const SESSIONS_CSV = path.join(DATA_DIR, "sessions.csv");

export async function clearAllDataStores(): Promise<void> {
  const SQL = await initSqlJs();

  // 1. Reset incidents.sqlite & incidents.csv
  let dbInc = new SQL.Database();
  dbInc.run(`
    CREATE TABLE incidents (
        event_id TEXT PRIMARY KEY,
        timestamp TEXT,
        session_id TEXT,
        asset_id TEXT,
        src_ip TEXT,
        dst_ip TEXT,
        attack_type TEXT,
        severity TEXT,
        mitre_id TEXT,
        zone TEXT,
        subnet TEXT,
        traffic_type TEXT,
        system_damage TEXT
    );
  `);
  dbInc.run("CREATE INDEX idx_zone ON incidents(zone);");
  dbInc.run("CREATE INDEX idx_subnet ON incidents(subnet);");
  dbInc.run("CREATE INDEX idx_srcip ON incidents(src_ip);");
  dbInc.run("CREATE INDEX idx_session ON incidents(session_id);");
  fs.writeFileSync(INCIDENTS_DB, Buffer.from(dbInc.export()));
  dbInc.close();

  fs.writeFileSync(
    INCIDENTS_CSV,
    `"event_id","timestamp","session_id","asset_id","src_ip","dst_ip","attack_type","severity","mitre_id","zone","subnet","traffic_type","system_damage"\n`
  );

  // 2. Reset tickets.sqlite & tickets.csv & proposals.csv
  let dbTick = new SQL.Database();
  dbTick.run(`
    CREATE TABLE tickets (
        ticket_id TEXT PRIMARY KEY,
        session_id TEXT,
        asset_id TEXT,
        severity TEXT,
        mitre_id TEXT,
        description TEXT,
        action_field TEXT,
        campaign_id TEXT,
        status TEXT,
        created_at TEXT
    );
  `);
  dbTick.run(`
    CREATE TABLE proposals (
        proposal_id TEXT PRIMARY KEY,
        session_id TEXT,
        asset_id TEXT,
        zone TEXT,
        reason TEXT,
        mitre_id TEXT,
        status TEXT,
        approved_by TEXT,
        created_at TEXT
    );
  `);
  fs.writeFileSync(TICKETS_DB, Buffer.from(dbTick.export()));
  dbTick.close();

  fs.writeFileSync(
    TICKETS_CSV,
    `"ticket_id","session_id","asset_id","severity","mitre_id","description","action_field","campaign_id","status","created_at"\n`
  );

  fs.writeFileSync(
    PROPOSALS_CSV,
    `"proposal_id","session_id","asset_id","zone","reason","mitre_id","status","approved_by","created_at"\n`
  );

  // 3. Reset sessions.sqlite & sessions.csv
  let dbSess = new SQL.Database();
  dbSess.run(`
    CREATE TABLE sessions (
        session_id TEXT PRIMARY KEY,
        start_time TEXT,
        end_time TEXT,
        total_events INTEGER,
        normal_count INTEGER,
        low_count INTEGER,
        medium_count INTEGER,
        high_count INTEGER,
        critical_count INTEGER,
        tickets_count INTEGER,
        proposals_count INTEGER,
        status TEXT
    );
  `);
  fs.writeFileSync(SESSIONS_DB, Buffer.from(dbSess.export()));
  dbSess.close();

  fs.writeFileSync(
    SESSIONS_CSV,
    `"session_id","start_time","end_time","total_events","normal_count","low_count","medium_count","high_count","critical_count","tickets_count","proposals_count","status"\n`
  );

  console.log(`[DATA RESET] Cleared all SQLite DBs and reset single CSV data stores in ${DATA_DIR}`);
}

export async function init_incidents_db(forceFresh: boolean = false): Promise<void> {
  if (forceFresh || !fs.existsSync(INCIDENTS_DB)) {
    await clearAllDataStores();
    return;
  }
}

export async function init_tickets_db(forceFresh: boolean = false): Promise<void> {
  if (forceFresh || !fs.existsSync(TICKETS_DB)) {
    await clearAllDataStores();
    return;
  }
}

export async function init_sessions_db(forceFresh: boolean = false): Promise<void> {
  if (forceFresh || !fs.existsSync(SESSIONS_DB)) {
    await clearAllDataStores();
    return;
  }
}

export const initIncidentsDb = init_incidents_db;
export const initTicketsDb = init_tickets_db;
export const initSessionsDb = init_sessions_db;

const isMain = Boolean(process.argv[1] && path.resolve(process.argv[1]) === path.resolve(__filename));
if (isMain) {
  (async () => {
    await clearAllDataStores();
  })();
}

import { createServer, Tool, z } from '@nitrostack/core';
import { WustlClassifier } from './detection/classifier.js';
import { getMitreMapping } from './agent/mitre.js';
import { engineManager } from './engine_runner.js';
import { clearAllDataStores } from '../data/database_setup.js';
import {
  AssetInfoController,
  TicketingController,
  ContainmentController,
  SessionController,
  querySqlite,
  INCIDENTS_DB,
  TICKETS_DB,
  SESSIONS_DB
} from './mcp_servers/mcp_servers.js';

const classifier = new WustlClassifier();
const assetInfo = new AssetInfoController();
const ticketing = new TicketingController();
const containment = new ContainmentController();
const sessionCtrl = new SessionController();

const server = createServer({
  name: 'intrusion',
  version: '1.0.0',
  description: 'NitroStack OT Security Response Server & Autonomous Engine Controller.',
});

// 0. Tool: clear_all_data_stores (RESET DATA STORES & CSV FILES)
server.tool(
  new Tool({
    name: 'clear_all_data_stores',
    description: 'Clear all historical data stores (incidents.sqlite, tickets.sqlite, sessions.sqlite, and single CSV files incidents.csv, tickets.csv, proposals.csv, sessions.csv). Starts fresh.',
    inputSchema: z.object({}).passthrough(),
    handler: async () => {
      await clearAllDataStores();
      return { status: "SUCCESS", message: "All SQLite databases and single CSV stores cleared and reset successfully." };
    }
  })
);

// 1. Tool: start_engine / run_engine (PROCESSES TELEMETRY EVENTS LIVE, UPDATING DB & CSV FOR EVERY PACKET, PROMPTING APPROVAL IMMEDIATELY)
server.tool(
  new Tool({
    name: 'start_engine',
    description: 'Run real-time intrusion detection engine session. Updates SQLite DB and single CSV files for EVERY network traffic packet. Immediately outputs High/Critical severity alerts and approval prompts directly in Chat.',
    inputSchema: z.object({
      event_count: z.number().optional().default(15).describe('Number of telemetry packets to stream in this step (default 15)')
    }).passthrough(),
    handler: async (rawInput) => {
      const input = (rawInput as any) || {};
      const count = Number(input.event_count || 15);
      return engineManager.runLiveSessionStep(count);
    }
  })
);

// Alias: run_engine calls start_engine handler logic
server.tool(
  new Tool({
    name: 'run_engine',
    description: 'Run real-time intrusion detection engine session. Updates SQLite DB and single CSV files for EVERY network traffic packet. Immediately outputs High/Critical severity alerts and approval prompts directly in Chat.',
    inputSchema: z.object({
      event_count: z.number().optional().default(15).describe('Number of telemetry packets to stream in this step (default 15)')
    }).passthrough(),
    handler: async (rawInput) => {
      const input = (rawInput as any) || {};
      const count = Number(input.event_count || 15);
      return engineManager.runLiveSessionStep(count);
    }
  })
);

// 2. Tool: stop_engine (STOPS ENGINE & RETURNS SESSION REPORT)
server.tool(
  new Tool({
    name: 'stop_engine',
    description: 'Stop the active continuous engine session, finalize session records in sessions.sqlite, and return complete session summary, tickets, proposals, and pending action items.',
    inputSchema: z.object({}).passthrough(),
    handler: async () => {
      return engineManager.stopEngine();
    }
  })
);

// 3. Tool: get_engine_status (CHECKS REAL-TIME ENGINE STATE & PAUSE STATUS)
server.tool(
  new Tool({
    name: 'get_engine_status',
    description: 'Check if the continuous engine is running or paused for CRITICAL attack approval, active session_id, and live counts of events processed so far.',
    inputSchema: z.object({}).passthrough(),
    handler: async () => {
      return engineManager.getStatus();
    }
  })
);

// 4. Tool: get_session_details (RETRIEVES ATTACKS, TICKETS, PROPOSALS SEPARATELY PER SESSION)
server.tool(
  new Tool({
    name: 'get_session_details',
    description: 'Retrieve stored attack telemetry, work order tickets, and proposals filtered strictly by session_id.',
    inputSchema: z.object({
      session_id: z.string().describe('Target session ID (e.g. SES-XXXXXX)')
    }).passthrough(),
    handler: async (rawInput) => {
      const input = (rawInput as any) || {};
      const sid = input.session_id;
      if (!sid) return { error: "session_id parameter is required" };

      const attacks = querySqlite(INCIDENTS_DB, "SELECT * FROM incidents WHERE session_id = ?", [sid]);
      const tickets = querySqlite(TICKETS_DB, "SELECT * FROM tickets WHERE session_id = ?", [sid]);
      const proposals = querySqlite(TICKETS_DB, "SELECT * FROM proposals WHERE session_id = ?", [sid]);

      return {
        session_id: sid,
        total_attacks: attacks.length,
        total_tickets: tickets.length,
        total_proposals: proposals.length,
        attacks,
        tickets,
        proposals
      };
    }
  })
);

// 5. Tool: get_summary_report (EXECUTIVE REPORT GENERATION)
server.tool(
  new Tool({
    name: 'get_summary_report',
    description: 'Retrieve executive summary report of ALREADY STORED events and sessions in SQLite database.',
    inputSchema: z.object({}).passthrough(),
    handler: async (rawInput, context) => {
      context.logger.info('Running get_summary_report');
      try {
        const events = querySqlite(INCIDENTS_DB, "SELECT * FROM incidents");
        const tickets = querySqlite(TICKETS_DB, "SELECT * FROM tickets");
        const proposals = querySqlite(TICKETS_DB, "SELECT * FROM proposals");
        const sessions = sessionCtrl.getStoredSessions();

        let normalCount = 0, lowCount = 0, mediumCount = 0, highCount = 0, criticalCount = 0;
        for (const ev of events) {
          const sev = (ev.severity || "").toUpperCase();
          if (sev === "NORMAL" || ev.traffic_type === "normal") normalCount++;
          else if (sev === "LOW") lowCount++;
          else if (sev === "MEDIUM") mediumCount++;
          else if (sev === "HIGH") highCount++;
          else if (sev === "CRITICAL") criticalCount++;
        }

        const pendingProposals = proposals.filter((p: any) => p.status === "pending_approval");

        return {
          report_title: "OT SECURITY EXECUTIVE SUMMARY REPORT",
          generated_at: new Date().toISOString(),
          total_sessions_run: sessions.length,
          total_historical_events_stored: events.length,
          breakdown: {
            normal_operational_traffic: normalCount,
            low_severity_attacks: lowCount,
            medium_severity_attacks: mediumCount,
            high_severity_attacks: highCount,
            critical_severity_attacks: criticalCount
          },
          total_tickets_created: tickets.length,
          total_proposals_generated: proposals.length,
          pending_proposals_requiring_approval: pendingProposals,
          recent_sessions: sessions.slice(0, 5)
        };
      } catch (err: any) {
        return { error: err.message, status: 'failed' };
      }
    }
  })
);

// 6. Tool: list_stored_sessions (SESSION QUERYING)
server.tool(
  new Tool({
    name: 'list_stored_sessions',
    description: 'Retrieve details of execution sessions stored in sessions.sqlite.',
    inputSchema: z.object({}).passthrough(),
    handler: async (rawInput, context) => {
      context.logger.info('Running list_stored_sessions');
      try {
        return sessionCtrl.getStoredSessions();
      } catch (err: any) {
        return [];
      }
    }
  })
);

// 7. Tool: list_stored_events (HISTORICAL TELEMETRY)
server.tool(
  new Tool({
    name: 'list_stored_events',
    description: 'Query historical security telemetry events stored in incidents.sqlite.',
    inputSchema: z.object({
      limit: z.number().optional().default(20).describe('Max events to retrieve (default 20)'),
      severity: z.string().optional().describe('Filter by severity: LOW, MEDIUM, HIGH, CRITICAL, NORMAL')
    }).passthrough(),
    handler: async (rawInput, context) => {
      context.logger.info('Running list_stored_events');
      try {
        const input = (rawInput as any) || {};
        return assetInfo.getStoredEvents(Number(input.limit || 20), input.severity);
      } catch (err: any) {
        return [];
      }
    }
  })
);

// 8. Tool: get_stored_tickets (TICKET MANAGEMENT)
server.tool(
  new Tool({
    name: 'get_stored_tickets',
    description: 'Retrieve work order tickets stored in tickets.sqlite created during engine sessions.',
    inputSchema: z.object({}).passthrough(),
    handler: async (rawInput, context) => {
      context.logger.info('Running get_stored_tickets');
      try {
        return ticketing.getStoredTickets();
      } catch (err: any) {
        return [];
      }
    }
  })
);

// 9. Tool: get_stored_proposals (PROPOSAL MANAGEMENT)
server.tool(
  new Tool({
    name: 'get_stored_proposals',
    description: 'Retrieve containment & isolation proposals stored in tickets.sqlite awaiting operator approval.',
    inputSchema: z.object({}).passthrough(),
    handler: async (rawInput, context) => {
      context.logger.info('Running get_stored_proposals');
      try {
        return containment.getStoredProposals();
      } catch (err: any) {
        return [];
      }
    }
  })
);

// 10. Tool: get_asset (ASSET INVENTORY)
server.tool(
  new Tool({
    name: 'get_asset',
    description: 'Lookup asset metadata, zone, subnet, and criticality from assets.csv.',
    inputSchema: z.object({
      ip_or_id: z.string().optional().describe('Target IP address or asset_id')
    }).passthrough(),
    handler: async (rawInput, context) => {
      context.logger.info('Running get_asset');
      try {
        const input = (rawInput as any) || {};
        const ipOrId = input.ip_or_id || input.ip || input.asset_id || (typeof rawInput === 'string' ? rawInput : '10.0.4.5');
        return assetInfo.getAsset(String(ipOrId).trim());
      } catch (err: any) {
        return { error: err.message, criticality: 'critical', type: 'Unknown' };
      }
    }
  })
);

// 11. Tool: get_mitre_mapping (MITRE ATT&CK LOOKUP)
server.tool(
  new Tool({
    name: 'get_mitre_mapping',
    description: 'Map an attack classification to MITRE ATT&CK for ICS matrix.',
    inputSchema: z.object({
      attack_type: z.string().optional().describe('Attack type string')
    }).passthrough(),
    handler: async (rawInput, context) => {
      context.logger.info('Running get_mitre_mapping');
      try {
        const input = (rawInput as any) || {};
        const attackType = input.attack_type || (typeof rawInput === 'string' ? rawInput : 'Reconn');
        return getMitreMapping(attackType);
      } catch (err: any) {
        return getMitreMapping('Reconn');
      }
    }
  })
);

// 12. Tool: execute_isolation (OPERATOR SIGN-OFF - STOPS ENGINE ON CRITICAL APPROVAL)
server.tool(
  new Tool({
    name: 'execute_isolation',
    description: 'Execute network isolation for a proposal stored in tickets.sqlite. REQUIRES mandatory approved_by operator sign-off. IF THE PROPOSAL IS CRITICAL, AUTOMATICALLY STOPS THE ENGINE SESSION FOR PLANT SAFETY.',
    inputSchema: z.object({
      proposal_id: z.string().optional().describe('Target proposal ID (e.g. PROP-XXXXXX)'),
      approved_by: z.string().optional().describe('Human operator ID/role giving sign-off')
    }).passthrough(),
    handler: async (rawInput, context) => {
      context.logger.info('Running execute_isolation');
      try {
        const input = (rawInput as any) || {};
        const proposalId = input.proposal_id || 'PROP-001';
        const approvedBy = input.approved_by || 'operator_plant_mgr';

        const execRes = containment.executeIsolation(proposalId, approvedBy);

        // Check if engine is paused for Critical Approval
        if (engineManager.isPaused() || engineManager.getCriticalProposalId() === proposalId) {
          const sessionStopRes = engineManager.notifyCriticalApprovalAndStop(proposalId, approvedBy);
          return {
            execution_result: execRes,
            critical_safety_notice: "CRITICAL SEVERITY ATTACK ISOLATION APPROVED BY OPERATOR. SESSION HAS BEEN TERMINATED FOR PLANT SAFETY.",
            session_result: sessionStopRes
          };
        }

        return execRes;
      } catch (err: any) {
        return { status: 'BLOCKED', error: err.message };
      }
    }
  })
);

